    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// export * from 'foo';
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// export * as foo from 'foo';
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// export { foo } from "foo";
    /// ```
    ///
    pub NoReExportAll {
        version: "next",
        name: "noReExportAll",
        recommended: false,
        source: RuleSource::EslintBarrelFiles("avoid-re-export-all"),
        source_kind: RuleSourceKind::SameLogic,
    }
}

