        let node = ctx.query();
        node.export_clause()
            .ok()?
            .as_js_export_from_clause()
            .and_then(|clause| {
                if clause.from_token().is_ok() && clause.star_token().is_ok() {
                    Some(())
                } else {
                    None
                }
            })
