declare_rule! {
    /// Disallow the use of barrel file.
    ///
    /// A barrel file is a file that re-exports all of the exports from other files in a directory.
    /// This structure results in the unnecessary loading of many modules, significantly impacting performance in large-scale applications.
    /// Additionally, it complicates the codebase, making it difficult to navigate and understand the project's dependency graph.
    /// This rule ignores dynamic imports like `import('./foo')` and `export * from './foo'`.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// export * from "foo";
    /// export * from "bar";
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// export { foo } from "foo";
    /// export { bar } from "bar";
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// export { default as module1 } from "./module1";
    /// export { default as module2 } from "./module2";
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// export type * from "foo";
    /// export type * from "bar";
    /// ```
    ///
    /// ```js
    /// export type { foo } from "foo";
    /// export type { bar } from "bar";
    /// ```
    ///
    pub NoBarrelFile {
        version: "next",
        name: "noBarrelFile",
        recommended: false,
        source: RuleSource::EslintBarrelFiles("avoid-barrel-files"),
        source_kind: RuleSourceKind::Inspired,
    }
}

impl Rule for NoBarrelFile {
    type Query = Ast<JsExport>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let export = ctx.query();
        let export_clause = export.export_clause().ok()?;
        let is_barrel_file = match export_clause {
            // `export * from '...'` and `export * as ns from '...'`
            // but not `export type * from '...'` nor `export type * as ns from '...'`
            AnyJsExportClause::JsExportFromClause(clause) => clause.type_token().is_none(),
            // `export { foo } from '...'`, `export { foo as bar } from '...'`,
            // `export { default as bar } from '...'` and `export { foo, type Bar } from '...'`
            // but not `export type { ... } from '...'`
            AnyJsExportClause::JsExportNamedFromClause(clause) => clause.type_token().is_none(),
            _ => false,
        };
        is_barrel_file.then_some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Avoid barrel files, they slow down performance, and cause large module graphs with modules that go unused."
                },
            )
            .note(markup! {
                "Check this thorough explanation to better understand the context."
            }),
        )
    }
}
